export const RecipesCodecs = {
  recipe    : recordCodecs.json<RecipeData>({ validator: moduleValidators.validateRecipeData }),
  variation : recordCodecs.json<VariationData>({ validator: moduleValidators.validateVariationData }),
  editor    : recordCodecs.json<EditorData>({ validator: moduleValidators.validateEditorData }),
  viewer    : recordCodecs.json<ViewerData>({ validator: moduleValidators.validateViewerData }),
} as const;

